    LPWSTR* wideArgv = CommandLineToArgvW(commandLine, &wargc);
    for (int i = 0, j = 0; j < argc; i++, j++) {
        int byteSize = WideCharToMultiByte(CP_UTF8, 0, wideArgv[i], -1, nullptr, 0, nullptr, nullptr);
